{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C56"],
      "claim": "Sorafenib absolute oral bioavailability was about 50% in humans under fasted conditions, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Safinamide absolute oral bioavailability was 95% in healthy subjects after a 50 mg immediate-release tablet, indicating near-complete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "The active metabolite of nabumetone had a mean absolute bioavailability of 38% after oral administration, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Atenolol absolute bioavailability was 0.56 ± 0.17 after a 100 mg oral solution in normal subjects, above the 20% threshold despite its polar hydroxyl and amide groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Betaxolol absolute bioavailability was 83.9 ± 6.6% after a 40 mg oral capsule, supporting high oral availability for an aryl ether-containing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A structurally related heteroaryl ether with chlorophenyl and nitrile groups showed essentially 100% absolute oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Posaconazole suspension absolute bioavailability was estimated at 16% (8–27%) in immunocompromised pediatric patients, below the threshold; this is the main contradictory observation but reflects a specific formulation and patient population.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transferability direct absolute bioavailability measurements in humans, ranging from 38% to 100%, consistently support F >= 20%. The only sub-threshold observation is posaconazole suspension in pediatric patients, which is outweighed by the broader dataset and by the favorable physicochemical prior for the query.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the query molecule itself.",
    "The query's dioxolane acetal and multiple hydroxyl groups could confer acid lability or conjugative first-pass metabolism not fully captured by the analogues.",
    "Most analogue data come from healthy adults or specific patient populations; formulation and food effects for the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

